"""Whole rational approximation implementation, interface and KUnit suite."""
ROWS = []


def add(path, title, intro, principle, use, sections, questions):
    ROWS.append(dict(path=path, title=title, intro=intro, principle=principle,
                     use=use, area='연분수 · 근사 알고리즘·제한 최적화',
                     sections=sections, questions=questions))


add('lib/math/rational.c', '유리수 근사 전체: 연분수와 레지스터 크기 제한',
    '분자와 분모의 상한이 있을 때 원하는 비율에 가까운 분수를 선택합니다.',
    '유클리드 알고리즘의 몫 a를 연분수 항으로 사용합니다. 앞선 두 근사 n0/d0,n1/d1로 n2=n0+a*n1,d2=d0+a*d1을 만들고 제한을 넘으면 이전 근사와 가능한 중간 근사를 비교합니다.',
    'PLL 등의 제한된 분자·분모 필드에 맞는 비율을 찾는 용도입니다. unsigned long 산술과 출력 포인터를 사용하며 일반 부동소수점 함수나 checked arithmetic API가 아닙니다.',
    [('파일 전체', 'SPDX·저작권·용도와 예제 주석, rational/compiler/export/minmax/limits/module 헤더, rational_best_approximation 하나, 공개 export, 모듈 설명·GPL v2 정보로 구성됩니다. 원문의 예시는31415/10000,분자 최대255,분모 최대31입니다.'),
     ('초기 상태와 유클리드 단계', 'n,d는 입력 비율이고 n0/d0=0/1,n1/d1=1/0으로 시작합니다.1/0은 정상적인 최종 유리수가 아니라 재귀식을 시작하는 표식입니다. d가0인지 먼저 검사한 뒤 dp=d,a=n/d,d=n%d,n=dp로 갱신합니다. dp는 갱신 전 분모를 보존합니다.'),
     ('수렴분수 갱신', 'n2,d2가 두 상한 안에 있으면 이전 상태를 한 단계 이동합니다. 예를 들어3/2의 첫 몫1은1/1,다음 몫2는3/2를 만들며 나머지0에서 종료합니다. 매번 모든 후보 분자를 열거하지 않고 연분수 구조를 이용합니다.'),
     ('상한을 처음 넘는 순간', 't는 ULONG_MAX에서 시작하고 d1이 비영이면(max_denominator-d0)/d1, n1이 비영이면(max_numerator-n0)/n1과의 최솟값으로 제한됩니다. 후보는(n0+t*n1)/(d0+t*d1)입니다. 이전 항이0인 경우 나누지 않도록 분기합니다. 제한 계산도 unsigned이므로 범위·중간 연산의 전제를 무시한 임의 입력 안전성을 뜻하지 않습니다.'),
     ('중간 근사 선택 조건', 'd1==0이면 아직 이전 정상 분모가 없으므로 중간 근사를 선택합니다. 그 외에는2*t>a이거나,같을 때 d0*dp>d1*d이면 선택합니다. 조건이 거짓이면 이전 n1/d1을 유지합니다. 이 비교를 단순히 가장 큰 분모를 항상 고른다고 요약하면 실제 선택을 놓칩니다.'),
     ('0에 가까운 값', '입력1/30에 분모 상한10이면0/1이1/10보다 가깝습니다. 반면1/19에는1/10이0보다 가깝습니다. 정상적인 입력에서도 최적 분자가0일 수 있으므로 비영 분자를 반드시 얻는 API가 아닙니다.'),
     ('출력과 경계', '끝에서 두 출력 포인터를 역참조하여 n1,d1을 씁니다. NULL 검사·할당·에러 반환은 없습니다. 입력 분모0이면 첫 반복 전에 종료해 초기1/0을 쓰므로 유효한 유리수 계산으로 받아들이면 안 됩니다. 양의 분모 상한, 표현 가능한 중간 곱·합 등 호출 범위를 확인해야 합니다. 특히 2*t와 비교용 곱에도 오버플로 검사가 없습니다.'),
     ('CS와 독립 검증', '유클리드 나머지의 감소, 연분수 수렴분수, 두 상한을 만족하는 최적화, 고정 폭 산술을 연결합니다. 작은 입력 영역에서는 가능한 모든0<=p<=max_numerator,1<=q<=max_denominator를 열거해 오차를 정확한 정수 교차곱으로 비교하면 알고리즘과 다른 방식으로 검산할 수 있습니다. 작은 영역 통과를 모든 기계 정수에 대한 증명으로 확대하지 않습니다.')],
    [('입력1/30,분모 상한10에서0/1을 반환할 수 있는 이유는?', '1/10보다 오차가 작기 때문이다', '분자0은 계산 실패 코드이기 때문이다', '0의 오차는1/30이고1/10의 오차는1/15입니다. 분자0은 정상적인 근사 결과가 될 수 있습니다.'),
     ('초기 n1/d1=1/0은 어떤 역할인가?', '연분수 재귀식의 시작 표식이다', '항상 반환할 정상적인 분수다', '정상 입력은 반복을 통해 유효 후보를 만듭니다. 분모0 입력은 이 초기 상태에서 바로 종료하므로 유효한 근사 입력으로 쓰지 않습니다.'),
     ('n2/d2가 상한을 넘으면 무조건 이전 분수를 반환하는가?', '아니다. 가능한 중간 근사와 비교하여 선택한다', '그렇다. t는 결과에 사용하지 않는다', 't로 n0+t*n1,d0+t*d1을 만들 수 있으며2*t와 a 및 나머지 관계로 선택합니다.'),
     ('이 함수가 NULL 출력 포인터를 오류 코드로 처리하는가?', '아니다. 종료 시 두 포인터에 직접 쓴다', '그렇다. 반환값이 음수이면 NULL이었다', '반환형은 void이고 출력 포인터 검사가 없습니다. 호출자는 쓰기 가능한 출력 저장소를 제공해야 합니다.')])

add('include/linux/rational.h', '유리수 인터페이스 전체: 네 입력과 두 출력의 계약',
    '근사 비율과 표현 가능한 레지스터 범위를 별개의 인자로 전달합니다.',
    'given_numerator/given_denominator가 원하는 비율, max_numerator/max_denominator가 허용 상한이며 best_numerator/best_denominator 포인터로 결과를 돌려줍니다.',
    '6개 인자는 모두 unsigned long 또는 그 포인터입니다. signed 음수,임의 정밀도,별도 오류 상태를 표현하는 인터페이스가 아닙니다.',
    [('파일 전체 구성', 'SPDX,저작권과 PLL 활용 주석, _LINUX_RATIONAL_H guard,단일 함수 선언,#endif가 전부입니다. 구현·상수 표·별도 구조체 정의는 없습니다.'),
     ('입력과 출력 구분', '처음4개는 값으로 전달되어 호출자의 변수 자체를 수정하지 않습니다. 마지막2개는 출력 저장소 주소입니다. 출력 두 개를 별도로 받으려면 별도 저장소를 제공해야 하며 같은 주소를 전달하면 구현의 마지막 쓰기가 앞선 값을 덮습니다.'),
     ('선언의 한계', 'void 반환은 성공·실패 정수 코드를 주지 않는다는 뜻입니다. 유효 분모,상한,산술 범위,포인터 유효성은 구현과 사용처를 함께 검토해야 합니다. 함수 이름 best가 모든 잘못된 입력을 복구한다는 뜻은 아닙니다.')],
    [('max_numerator는 원하는 분자와 같은 의미인가?', '아니다. 결과 분자의 허용 상한이다', '그렇다. 같은 입력을 두 번 전달하는 것이다', 'given은 목표 비율이고 max는 하드웨어 등에서 허용되는 범위입니다. 둘을 분리해야 제한 근사가 가능합니다.'),
     ('분자와 분모 출력 포인터에 같은 주소를 주면 두 값을 보존하는가?', '아니다. 같은 저장소의 두 번째 쓰기가 첫 값을 덮는다', '그렇다. void 함수가 자동으로 두 값을 포장한다', '구현은 *best_numerator 후 *best_denominator에 순서대로 대입합니다. 두 결과가 필요하면 저장소도 구분합니다.')])

add('lib/math/rational-test.c', '유리수 KUnit 전체: 8개 사례와 분자·분모별 검증',
    '알고리즘의 선택 경로를 겨냥한 표 기반 단위 테스트입니다.',
    'rational_test_param은 목표 비율,상한,기대 분자·분모,이름을 담습니다. KUNIT_ARRAY_PARAM 생성기를 KUNIT_CASE_PARAM에 연결하여8개 행을 각각 실행합니다.',
    '명시 사례는 큰 값의 제한,0 근처,이전 수렴분수 선택,정확한 약분 결과,분자 또는 분모 상한의 중간 근사를 포함합니다. 전체 입력 공간 검증은 아닙니다.',
    [('8개 기대 결과', '1230/10→100/1,34567/100→120/1,1/30→0/1,1/19→1/10,27/32→11/13,1155/7735→33/221,87/32→68/25,14533/4626→7433/2366입니다. 각 행의 상한이 다르므로 비율만 보고 기대값을 재사용하지 않습니다.'),
     ('실행 함수와 설명', 'get_desc는 사례 이름을 크기 제한 strscpy로 복사합니다. rational_test는 n,d를0으로 초기화하고 실제 함수를 호출한 뒤 KUNIT_EXPECT_EQ 두 번으로 분자와 분모를 각각 검사합니다. 실수로 나눈 값만 비교하지 않습니다.'),
     ('등록과 메타데이터', '빈 {}로 끝나는 kunit_case 배열,이름 rational의 suite,kunit_test_suites 등록,모듈 설명과 GPL v2 라이선스로 끝납니다. 원본 전체는 데이터 정의·설명 생성·실행·등록 단계로 나뉩니다.'),
     ('검증 범위', '1/30과1/19 두 사례는0/1 선택과 가장 작은 비영 후보 선택의 차이를 확인합니다. Exact answer 사례는1155/7735를35로 약분한33/221입니다. 입력 분모0,기계 정수 최대값 근처의 중간 오버플로,모든 상한 조합은 이 표에 없습니다. 파일을 읽은 것만으로 KUnit을 커널에서 실행했다고 주장할 수 없습니다.')],
    [('이 테스트는 분수를 실수로 바꾸어 한 번만 비교하는가?', '아니다. 분자와 분모를 각각 기대값과 비교한다', '그렇다. 실수 오차만 비교한다', '두 KUNIT_EXPECT_EQ가 n과d를 따로 검사합니다. 같아 보이는 실수 근사만으로 통과하는 테스트가 아닙니다.'),
     ('1155/7735의 정확한 기대 분수는?', '33/221', '33/255', '분자와 분모를35로 나누면33/221입니다. 상한255는 분모를 무조건255로 만들라는 지시가 아닙니다.'),
     ('8개 사례가 통과하면 모든 오버플로 경계도 증명되는가?', '아니다. 테스트에 없는 입력 영역은 별도 검증해야 한다', '그렇다. 분기 이름을 나열하면 모든 정수 입력을 포괄한다', '사례의 설명 이름은 커버리지 증명서가 아닙니다. 실제 수치와 타입 범위를 기준으로 검증 범위를 판단합니다.')])
